let launched=false;const note=document.querySelector('#notice');async function request(url,data){const r=await fetch(url,{method:data?'POST':'GET',headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});const b=await r.json();if(!r.ok)throw Error(b.error||'Anfrage fehlgeschlagen');return b}async function refresh(){try{const s=await request('/api/admin/state');document.querySelector('#login').hidden=true;document.querySelector('#panel').hidden=false;launched=s.launched;document.querySelector('#gateState').textContent=launched?'SHOP IST OFFEN.':'GATE IST GESCHLOSSEN.';document.querySelector('#toggleGate span').textContent=launched?'Gate wieder schließen':'Launch freigeben';document.querySelector('#priceInput').value=s.price;document.querySelector('#counts').textContent=`${s.subscribers.total} Einträge / ${s.subscribers.confirmed||0} bestätigte Adressen`;document.querySelector('#mailState').textContent=s.waitlistReady?'Anmeldung und Bestätigungsversand sind konfiguriert.':'Adressen werden vorgemerkt. Bestätigungsversand wartet auf Absender und Betreiberangaben.'}catch{document.querySelector('#panel').hidden=true;document.querySelector('#login').hidden=false}}document.querySelector('#login').onsubmit=async e=>{e.preventDefault();try{await request('/api/admin/login',{password:document.querySelector('#password').value});document.querySelector('#password').value='';note.textContent='';await refresh()}catch(err){note.textContent=err.message}};document.querySelector('#priceForm').onsubmit=async e=>{e.preventDefault();try{await request('/api/admin/price',{price:Number(document.querySelector('#priceInput').value)});note.textContent='Preis gespeichert.';await refresh()}catch(err){note.textContent=err.message}};document.querySelector('#toggleGate').onclick=async()=>{if(!confirm(launched?'Gate wieder schließen?':'Shop jetzt für alle Besucher öffnen?'))return;try{await request('/api/admin/launch',{launched:!launched});note.textContent='Gate-Status gespeichert.';await refresh()}catch(err){note.textContent=err.message}};refresh();

async function loadOrders(){
 const response=await fetch('/api/admin/orders');if(!response.ok)throw Error('Bestellungen konnten nicht geladen werden.');
 const data=await response.json(),list=document.querySelector('#orders');list.replaceChildren();
 for(const row of data.orders){const card=document.createElement('article');card.style.cssText='border-top:1px solid #ffffff30;padding:16px 0;overflow-wrap:anywhere';const title=document.createElement('h3');title.textContent=row.id;const detail=document.createElement('p');detail.textContent=[row.provider+' / '+row.payment_method+' / '+row.status,new Date(row.created_at).toLocaleString('de-DE'),row.items.map(x=>x.size+' × '+x.qty).join(', '),row.totalCents!==null?(row.totalCents/100).toFixed(2)+' EUR':null,row.details?Object.values(row.details).join(', '):null,row.session_id].filter(Boolean).join('\n');detail.style.whiteSpace='pre-wrap';card.append(title,detail);
 const actions=row.provider==='manual'&&row.status==='awaiting_payment'?[['confirm_payment','Zahlungseingang bestätigen'],['cancel','Bestellung stornieren']]:row.provider==='paypal'?[['reconcile_paypal','PayPal-Status abgleichen']]:[];
 for(const [action,label]of actions){const button=document.createElement('button');button.className='small-link';button.textContent=label;button.onclick=async()=>{if(action!=='reconcile_paypal'&&!confirm(label+' für '+row.id+'?'))return;button.disabled=true;try{const r=await fetch('/api/admin/orders/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:row.id,action})});if(!r.ok)throw Error('Aktion nicht bestätigt. Bitte Status prüfen.');await loadOrders()}catch(e){document.querySelector('#notice').textContent=e.message;button.disabled=false}};card.append(button)}list.append(card)}
 if(!data.orders.length)list.textContent='Noch keine Bestellungen.';
}
document.querySelector('#refreshOrders').onclick=()=>loadOrders().catch(e=>document.querySelector('#notice').textContent=e.message);
